import { IntlProvider } from 'react-intl';
import baseTheme from 'app/theme';

import { ZimmProductName as AName } from 'app/components/ui-kits/atoms/zimmProductName';
import { ZimmProductPrice as APrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
import { ZimmProductDescription as ADesc } from 'app/components/ui-kits/atoms/zimmProductDescription';
import { ZimmProductModelInfo as AModel } from 'app/components/ui-kits/atoms/zimmProductModelInfo';
import { ZimmProductStyleCode as AStyle } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
import { ZimmProductName as BName } from './before/zimmProductName';
import { ZimmProductPrice as BPrice } from './before/zimmProductPrice';
import { ZimmProductDescription as BDesc } from './before/zimmProductDescription';
import { ZimmProductModelInfo as BModel } from './before/zimmProductModelInfo';
import { ZimmProductStyleCode as BStyle } from './before/zimmProductStyleCode';
import { ZimmProductName as RName } from './before/zimmProductName.css';
import { ZimmProductPrice as RPrice } from './before/zimmProductPrice.css';
import { ZimmProductDescription as RDesc } from './before/zimmProductDescription.css';
import { ZimmProductModelInfo as RModel } from './before/zimmProductModelInfo.css';
import { ZimmProductStyleCode as RStyle } from './before/zimmProductStyleCode.css';

const themeBefore = {
  ...baseTheme,
  components: {
    ...(baseTheme as any).components,
    ZimmProductName: RName, ZimmProductPrice: RPrice, ZimmProductDescription: RDesc,
    ZimmProductModelInfo: RModel, ZimmProductStyleCode: RStyle,
  },
};
const PROPS = ['font-size','line-height','font-weight','letter-spacing','font-family','text-transform',
  'color','margin-top','margin-bottom','margin-left','margin-right','display','gap',
  'padding-inline-start','margin-block-start','white-space'];

const snap = (ui: React.ReactElement, theme: unknown) => {
  document.querySelectorAll('style[data-emotion]').forEach((s) => s.remove());
  const cache = createCache({ key: 'css' });
  const { container } = render(
    <CacheProvider value={cache}><ChakraProvider theme={theme as never} resetCSS={false}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">{ui}</IntlProvider>
    </ChakraProvider></CacheProvider>);
  const els = Array.from(container.querySelectorAll('*'));
  const classes = new Set(els.flatMap((el) => Array.from(el.classList)));
  const allCss = Array.from(document.querySelectorAll('style[data-emotion]')).map((s) => s.textContent ?? '').join('\n');
  // strip emotion hashes so only the DECLARATIONS are compared
  const decls = allCss.split('}')
    .filter((r) => [...classes].some((c) => r.includes('.' + c)))
    .map((r) => r.replace(/\.css-[a-z0-9]+/g, '.X').trim() + '}')
    .sort().join('\n');
  const computed = els.map((el) => ({ tag: el.tagName, testid: el.getAttribute('data-testid'), text: el.textContent,
    style: Object.fromEntries(PROPS.map((p) => [p, getComputedStyle(el).getPropertyValue(p)])) }));
  const skeleton = container.innerHTML.replace(/class="css-[a-z0-9]+"/g, 'class="X"');
  const hashes = [...classes].sort().join(',');
  cleanup();
  return { decls, computed, skeleton, hashes };
};

const CASES: Array<[string, React.ReactElement, React.ReactElement]> = [
  ['zimmProductName', <BName name="Natura Linen Mini Dress" as="h1" />, <AName name="Natura Linen Mini Dress" as="h1" />],
  ['zimmProductPrice', <BPrice price="$795" />, <APrice price="$795" />],
  ['zimmProductDescription', <BDesc description="<p>A</p><p>B</p><ul><li>1</li></ul>" />, <ADesc description="<p>A</p><p>B</p><ul><li>1</li></ul>" />],
  ['zimmProductModelInfo', <BModel modelInfo="<p>Model is 178cm</p>" />, <AModel modelInfo="<p>Model is 178cm</p>" />],
  ['zimmProductStyleCode', <BStyle value="8637DS241" />, <AStyle value="8637DS241" />],
];

describe('fix 2 — semantic equivalence (declarations + computed + DOM skeleton)', () => {
  test.each(CASES)('%s', (name, before, after) => {
    const b = snap(before, themeBefore);
    const a = snap(after, baseTheme);
    expect(b.decls).toMatch(/font-size/); // non-vacuity
    expect(a.computed, `${name}: computed drift`).toEqual(b.computed);
    expect(a.decls, `${name}: css declaration drift`).toBe(b.decls);
    expect(a.skeleton, `${name}: DOM skeleton drift`).toBe(b.skeleton);
    if (a.hashes !== b.hashes) console.log(`HASH CHANGED  ${name}: ${b.hashes}  ->  ${a.hashes}`);
    else console.log(`hash stable   ${name}: ${a.hashes}`);
  });
});
